public static int longestLine(int[][] mat) {
    int longest = 0;

    // Helper method to recursively search for a path
    public int maxLength(int[][] mat, int row, int col, int currentLength) {
        if (row >= mat.length || col >= mat[0].length) return 0;
        if (mat[row][col] != 1) return 0;

        // Mark the current cell as visited
        mat[row][col] = 0;

        // Check all four directions
        int maxLength = 0;
        maxLength = Math.max(maxLength, maxLength(mat, row + 1, col + 1, currentLength + 1));
        maxLength = Math.max(maxLength, maxLength(mat, row + 1, col, currentLength + 1));
        maxLength = Math.max(maxLength, maxLength(mat, row, col + 1, currentLength + 1));
        maxLength = Math.max(maxLength, maxLength(mat, row - 1, col - 1, currentLength));

        // Unmark the current cell
        mat[row][col] = 1;

        return maxLength;
    }

    // Maximize the length for each cell
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            longest = Math.max(longest, maxLength(mat, i, j, 1));
        }
    }

    return longest;
}

