    int result = 0;

    helper(A, n, 0, result);

    return result;
}

private static void helper(int[] A, int n, int i, int result) {
    if (i == n - 1) {
        if (A[i] * A[i] == A[i - 1])
            result++;
        return;
    }

    for (int j = i; j < n; j++) {
        if (A[j] < A[i])
            continue;

        swap(A, i, j);
        helper(A, n, i + 1, result);
        swap(A, i, j);
    }
}

