public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        throw new IllegalArgumentException("Array must contain three points.");
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Check for collinearity
    if ((y2 - y1) * (x3 - x2) == (x2 - x1) * (y3 - y2)) {
        return false;
    }

    // Check if the points form a boomerang
    return (y1 - y2) * (x3 - x2) * (y2 - y3) * (x2 - x3) > 0 ? true : false;
}

