    Queue<Long> q = new PriorityQueue<>();
    HashSet<Long> set = new HashSet<>();
    q.offer(1L);
    set.add(1L);
    int count = 0;
    long ugly = 0;

    while (true) {
        ugly = q.poll();
        set.remove(ugly);
        count++;
        if (count == n) {
            return (int) ugly;
        }
        q.offer(ugly * 2);
        q.offer(ugly * 3);
        q.offer(ugly * 5);
        set.add(ugly * 2);
        set.add(ugly * 3);
        set.add(ugly * 5);
    }
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxEnergy = 1, currentEnergy = 1;
    char lastChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == lastChar) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
        lastChar = s.charAt(i);
    }

    return Math.max(maxEnergy, currentEnergy);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result);
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNumbers = new HashSet<>();
    for (int num : nums) {
        uniqueNumbers.add(num);
    }
    int sum = 0;
    for (int num : uniqueNumbers) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.length() < 1) {
        return "";
    }
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        for (int i = 0; i < word.length() / 2; i++) {
            char temp = reversedWord.charAt(i);
            reversedWord.setCharAt(i, reversedWord.charAt(word.length() - 1 - i));
            reversedWord.setCharAt(word.length() - 1 - i, temp);
        }
        reversedSentence.append(reversedWord.toString());
        reversedSentence.append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().replaceAll("( )+", " ").trim();
}
